(28461, 'Romans 14:22', 'Romans', 14, 22, 'په کوم شي چې ته عقیده لرې، هغه د خدای او په خپل منځ کې وساته. بختور دي هغه خلک چې خپل ځانونه د هغه څه په خاطر چې د هغوی په نظر کې سم دي او تر‌سره کوي یې، مجرم نه ګڼي.', 'په کوم شی چې ته عقیده لرې، هغه د خدای او په خپل منج کې وساته. بختور دی هغه خلک چې خپل جانونه د هغه چه په خاطر چې د هغوی په نظر کې سم دی او تر‌سره کوی یې، مجرم نه ګنی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Romans_14_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28462, 'Romans 14:23', 'Romans', 14, 23, 'خو که چېرې څوک کوم څه وخوري او په هغه باندې شکمن وي، نو هغه محکوم دی، ځکه چې هغه د ایمان له مخې دا عمل نه کوي او هر عمل چې د ایمان له مخې نه وي، هغه ګناه ده.', 'خو که چېرې چوک کوم چه وخوری او په هغه باندې شکمن وی، نو هغه محکوم دی، جکه چې هغه د ایمان له مخې دا عمل نه کوی او هر عمل چې د ایمان له مخې نه وی، هغه ګناه ده.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Romans_14_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28463, 'John 12:1', 'John', 12, 1, 'د فسحې د اختر نه شپږ ورځې مخکې عیسی بیت‌عنیا ته چې ایلعازر په کې اوسېده، یعنې هماغه سړی چې هغه د مرګ نه وروسته بېرته راژوندی کړی ؤ، راغی.', 'د فسحې د اختر نه شپز ورجې مخکې عیسی بیت‌عنیا ته چې ایلعازر په کې اوسېده، یعنې هماغه سری چې هغه د مرګ نه وروسته بېرته راژوندی کری و، راغی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_12_1.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(28464, 'John 12:2', 'John', 12, 2, 'هغوی هلته د عیسی دپاره د ماښام ډوډۍ تیاره کړې وه. مرتا د هغوی خدمت کاوه او ایلعازر هم د عیسی سره ډوډۍ ته ناست ؤ.', 'هغوی هلته د عیسی دپاره د ماشام دودی تیاره کرې وه. مرتا د هغوی خدمت کاوه او ایلعازر هم د عیسی سره دودی ته ناست و.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_12_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28465, 'John 12:3', 'John', 12, 3, 'په دې وخت کې مریم یو بوتل قیمتي عطر چې نیم لیتر ؤ او د یو ډول خالصه خوشبویه ملهمو څخه جوړ شوي وو، راواخیستل او د عیسی په پښو باندې یې واچول او د هغه پښې یې په خپلو ویښتانو باندې وچې کړلې او ټول کور د عطرو د خوشبویۍ نه ډک شو.', 'په دې وخت کې مریم یو بوتل قیمتی عطر چې نیم لیتر و او د یو دول خالصه خوشبویه ملهمو چخه جور شوی وو، راواخیستل او د عیسی په پشو باندې یې واچول او د هغه پشې یې په خپلو ویشتانو باندې وچې کرلې او تول کور د عطرو د خوشبویی نه دک شو.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_12_3.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(28466, 'John 12:4', 'John', 12, 4, 'خو یهودا اسخریوتي چې د عیسی د شاګردانو څخه ؤ او وروسته یې د هغه سره خیانت وکړ، وویل:', 'خو یهودا اسخریوتی چې د عیسی د شاګردانو چخه و او وروسته یې د هغه سره خیانت وکر، وویل:', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_12_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28467, 'John 12:5', 'John', 12, 5, '«دا عطر ولې د درېو سوو سپینو زرو په سکو باندې خرڅ نه شول چې پیسې یې غریبانو ته ورکړل شوې وای؟»', '«دا عطر ولې د درېو سوو سپینو زرو په سکو باندې خرچ نه شول چې پیسې یې غریبانو ته ورکرل شوې وای؟»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_12_5.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(28468, 'John 12:6', 'John', 12, 6, 'هغه دا خبره د دې دپاره ونه کړه چې ګنې د هغه سره د غریبانو غم ؤ، بلکې په دې خاطر چې هغه خپله غل ؤ او څرنګه چې هغه د پیسو د ساتلو مسوولیت په غاړه درلود، نو اکثره وخت به یې یو څه پیسې د خپل ځان دپاره پټولې', 'هغه دا خبره د دې دپاره ونه کره چې ګنې د هغه سره د غریبانو غم و، بلکې په دې خاطر چې هغه خپله غل و او چرنګه چې هغه د پیسو د ساتلو مسوولیت په غاره درلود، نو اکثره وخت به یې یو چه پیسې د خپل جان دپاره پتولې', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_12_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28469, 'John 12:7', 'John', 12, 7, 'عیسی وویل: «د هغې سره کار مه لرئ، هغې زه د ښخولو دپاره تیار کړم.', 'عیسی وویل: «د هغې سره کار مه لری، هغې زه د شخولو دپاره تیار کرم.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_12_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28470, 'John 12:8', 'John', 12, 8, 'ځکه چې غریبان به تل ستاسو سره وي، خو زه به تل تاسو سره نه یم.» د ایلعازر په ضد دسیسه', 'جکه چې غریبان به تل ستاسو سره وی، خو زه به تل تاسو سره نه یم.» د ایلعازر په ضد دسیسه', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_12_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28471, 'John 12:9', 'John', 12, 9, 'زیات شمېر خلک خبر شول چې عیسی په بیت‌عنیا کې دی، نو هغوی هلته ورغلل. یوازې د دې دپاره نه چې عیسی وویني بلکې ایلعازر چې عیسی راژوندی کړی ؤ، هم وویني.', 'زیات شمېر خلک خبر شول چې عیسی په بیت‌عنیا کې دی، نو هغوی هلته ورغلل. یوازې د دې دپاره نه چې عیسی ووینی بلکې ایلعازر چې عیسی راژوندی کری و، هم ووینی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_12_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28472, 'John 12:10', 'John', 12, 10, 'نو مشرانو کاهنانو پرېکړه وکړه چې ایلعازر هم ووژني،', 'نو مشرانو کاهنانو پرېکره وکره چې ایلعازر هم ووژنی،', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_12_10.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(28473, 'John 12:11', 'John', 12, 11, 'ځکه چې د هغه له امله ډېرو خلکو هغوی پرېښودل او په عیسی باندې یې ایمان راوړ. په بریالیتوب سره اورشلیم ته د عیسی ننوتل (متي ۲۱‏:‌۱‌‏-‌۱۱ او مرقوس ۱۱‏:‌۱‌‏-‌۱۱ او لوقا ۱۹‏:‌۲۸‌‏-‌۴۰)', 'جکه چې د هغه له امله دېرو خلکو هغوی پرېشودل او په عیسی باندې یې ایمان راور. په بریالیتوب سره اورشلیم ته د عیسی ننوتل (متی ۲۱‏:‌۱‌‏-‌۱۱ او مرقوس ۱۱‏:‌۱‌‏-‌۱۱ او لوقا ۱۹‏:‌۲۸‌‏-‌۴۰)', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_12_11.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(28474, 'John 12:12', 'John', 12, 12, 'په بله ورځ ګڼ شمېر خلک چې د اختر دپاره راغلي وو، خبر شول چې عیسی اورشلیم ته راروان دی.', 'په بله ورج ګن شمېر خلک چې د اختر دپاره راغلی وو، خبر شول چې عیسی اورشلیم ته راروان دی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_12_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28475, 'John 12:13', 'John', 12, 13, 'نو هغوی د خرما د ونو څانګې واخیستلې او د هغه مخې ته ورووتل او چیغې یې وهلې: «ژوندی دې وي! مبارک دی وي هغه څوک چې د څښتن په نوم راځي! مبارک دي وي د اسراییلو پاچا!»', 'نو هغوی د خرما د ونو چانګې واخیستلې او د هغه مخې ته ورووتل او چیغې یې وهلې: «ژوندی دې وی! مبارک دی وی هغه چوک چې د چشتن په نوم راجی! مبارک دی وی د اسراییلو پاچا!»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_12_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28476, 'John 12:14', 'John', 12, 14, 'عیسی یو کوټی پیدا کړ او په هغه باندې سپور شو، لکه څنګه چې د خدای په کلام کې لیکل شوي دي:', 'عیسی یو کوتی پیدا کر او په هغه باندې سپور شو، لکه چنګه چې د خدای په کلام کې لیکل شوی دی:', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_12_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28477, 'John 12:15', 'John', 12, 15, '«ای د صهیون خلکو، نور مه وېرېږئ! ګوره، ستا پاچا دی راروان هغه سپور دی په کوټي باندې.»', '«ای د صهیون خلکو، نور مه وېرېزی! ګوره، ستا پاچا دی راروان هغه سپور دی په کوتی باندې.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_12_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(28478, 'John 12:16', 'John', 12, 16, 'په پیل کې شاګردان د دې شیانو په معنی باندې پوه نه شول، خو کله چې عیسی خپل جلال ته ورسېده، نو هغوی ته ور په یاد شول چې دا شیان د هغه په هکله لیکل شوي وو او د هغه سره همداسې وشول.', 'په پیل کې شاګردان د دې شیانو په معنی باندې پوه نه شول، خو کله چې عیسی خپل جلال ته ورسېده، نو هغوی ته ور په یاد شول چې دا شیان د هغه په هکله لیکل شوی وو او د هغه سره همداسې وشول.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_12_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28479, 'John 12:17', 'John', 12, 17, 'کله چې عیسی ایلعازر ته غږ وکړ او هغه یې راژوندی کړ او د قبر څخه یې راوویست، نو زیات شمېر خلک هلته موجود وو. هغوی چې څه لیدلي او اورېدلي وو د هغې په هکله یې نورو خلکو ته شاهدي ورکوله.', 'کله چې عیسی ایلعازر ته غز وکر او هغه یې راژوندی کر او د قبر چخه یې راوویست، نو زیات شمېر خلک هلته موجود وو. هغوی چې چه لیدلی او اورېدلی وو د هغې په هکله یې نورو خلکو ته شاهدی ورکوله.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_12_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28480, 'John 12:18', 'John', 12, 18, 'نو ګڼ شمېر خلک د هغه هرکلي ته ورغلل، ځکه چې هغوی اورېدلي وو چې عیسی دا معجزه ښودلې وه.', 'نو ګن شمېر خلک د هغه هرکلی ته ورغلل، جکه چې هغوی اورېدلی وو چې عیسی دا معجزه شودلې وه.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_12_18.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(28481, 'John 12:19', 'John', 12, 19, 'نو بیا فریسیانو یو بل ته سره وویل: «تاسو ګورئ چې مونږ هېڅ نه شو کولای، ټوله نړۍ هغه پسې روانه ده.» ځینې یونانیان غواړي چې د عیسی سره خبرې وکړي', 'نو بیا فریسیانو یو بل ته سره وویل: «تاسو ګوری چې مونز هېچ نه شو کولای، توله نری هغه پسې روانه ده.» جینې یونانیان غواری چې د عیسی سره خبرې وکری', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_12_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
